CREATE TABLE IF NOT EXISTS reconciliation_audit (provider TEXT NOT NULL,source TEXT NOT NULL,account_id TEXT NOT NULL,external_id TEXT NOT NULL,classification TEXT NOT NULL CHECK(classification IN ('exact_verified','probable_match','ambiguous','unmatched')),evidence_json TEXT NOT NULL,auto_export_allowed INTEGER NOT NULL DEFAULT 0 CHECK(auto_export_allowed=0),reviewed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(provider,source,account_id,external_id));